/* capcom_logo.h -- the CAPCOM intro logo sequence from Street Fighter II'
 * Special Champion Edition (USA): gold/blue CAPCOM logotype on black,
 * palette fade-in, a glint sweep at the jingle climax, fade-out -- plus the
 * FM jingle itself as a YM2612 register-stream replay (it is pure FM,
 * played by the 68k in the original; the Z80 only streams DAC silence).
 * GENERATED by capcom_intro_sf2/gen_capcom_kit.py -- do not hand-edit.
 * Extraction notes + provenance in capcom_intro_sf2/README.md.
 *
 * Minimal use (SGDK, after VDP_init; black palette assumed):
 *
 *   Z80_requestBus(TRUE);          // REQUIRED: the 68k can only reach the
 *                                  // YM while it owns the Z80 bus (without
 *                                  // this the jingle is silently dropped)
 *   capcom_intro_reset();          // also writes the YM patch state
 *   PAL_setColors(0, capcom_logo_cram, 16, CPU);
 *   capcom_logo_draw(TILE_USER_INDEX, 14, 12);   // (10,12) on H32 = original
 *   while (capcom_intro_step()) {                // ~6.0 s, returns 0 at end
 *       VDP_waitVSync();
 *       PAL_setColors(0, capcom_logo_cram, 16, CPU);
 *   }
 *   YM2612_reset();
 *   Z80_releaseBus();
 *
 * capcom_intro_step() drives the whole original timeline per call: jingle
 * replay via YM2612_writeReg (no other sound driver may touch the YM during
 * it), fade-in (t=34..58), glint (t=119..137), fade-out (t=333..357).
 * The CAPCOM logotype + jingle are CAPCOM's IP: personal homebrew only.
 */
#ifndef CAPCOM_LOGO_H
#define CAPCOM_LOGO_H

#include <genesis.h>

#define CAPCOM_LOGO_TILE_COUNT 36
#define CAPCOM_INTRO_FRAMES    360

extern const u32 capcom_logo_tiles[CAPCOM_LOGO_TILE_COUNT * 8];
extern u16 capcom_logo_cram[16];

/* Load tiles at vramBase and draw the 12x3 logo on BG_A at tile (x,y). */
void capcom_logo_draw(u16 vramBase, u16 x, u16 y);

void capcom_intro_reset(void);

/* One frame of the sequence (palette + jingle). Push capcom_logo_cram to
 * CRAM after each call. Returns 0 when the sequence is complete. */
u16 capcom_intro_step(void);

#endif
